arguments.command:
cd /tmp/ross-wt && printf '#!/bin/sh
case "$1" in
  *sername*) echo x-access-token ;;
  *assword*) echo "$GITHUB_TOKEN" ;;
esac
' > askpass.sh && chmod 700 askpass.sh && cd /tmp/ross-wt/convo && GIT_ASKPASS=/tmp/ross-wt/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/ross 2>&1 | tail -5
